# This formula is regenerated by the ankra-cli release workflow from
# packaging/homebrew/ankra.rb.tmpl in ankraio/ankra-cli. Manual edits here
# will be overwritten on the next release; change the template instead.
#
# There is deliberately no `version` stanza: `brew audit` fails a tap whose
# declared version it can already scan from the stable URL (redundant_version),
# and every release URL below carries the tag. That is why the URLs interpolate
# nothing - the release workflow substitutes the version into them directly.
class Ankra < Formula
  desc "Command-line interface for the Ankra Kubernetes platform"
  homepage "https://ankra.io"
  license "Apache-2.0"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.78.0/ankra-cli-darwin-arm64"
      sha256 "38217c096c3537f77e261b130632e4d77e4f5872bce81ffc46824425827d172a"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.78.0/ankra-cli-darwin-amd64"
      sha256 "1eff4e1c22461fd70b5a47d21e6e12020bcdb30b285a5a9af478790379f2dd25"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.78.0/ankra-cli-linux-arm64"
      sha256 "70eb90ae8a6d51e24f1162682a58ce17b4fa8f5d92b5804a593ddd8d8c5a0c96"
    end
    on_intel do
